import json,hashlib
from pathlib import Path
tag="p106b_repair_role_v1_s1337"; root=Path("."); corpus=root/"HF/sft_ready"/tag/"corpus"
rep=json.loads((corpus/"report.json").read_text()); rows=[]
for key in ("test_role_style0","test_role_style2"):
 for spec in rep["manifests"][key]["shards"]:
  rows.extend(json.loads(x) for x in (corpus/spec["path"]).read_text().splitlines())
def sha(v): return hashlib.sha256(json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(",",":")).encode()).hexdigest().upper()
groups={r["meta"]["neutral_root"]:r["meta"]["producer_graph"]["family"] for r in rows}
chosen={f:min([k for k,v in groups.items() if v==f],key=lambda k:sha([tag,"FIXED_MANUAL_ROLE",k])) for f in ("people","units","transfer","years")}
events={}
for arm in ("parent","raw_repeat","repair_repeat","raw_role","repair_role"):
 d=root/"test_result/evidence/local"/tag/"evaluate"/arm
 events[arm]=[json.loads(x) for x in (d/"role_bridge_000000.jsonl").read_text().splitlines()]
def text(m):return "".join(x["text"] for x in m["content"])
out=[]
for f,neutral in chosen.items():
 item={"family":f,"neutral":neutral,"selection":"SHA(TAG,FIXED_MANUAL_ROLE,neutral) first1/family","cases":[]}
 for r in rows:
  if r["meta"]["neutral_root"]!=neutral: continue
  m=r["meta"]; key=m["semantic_root_id"]; case={"lang":m["language"],"style":m["question_style"],"view":m["view"],"fields":m["requested_fields"],"reference_and_q1":text(r["messages"][0]),"q2":text(r["messages"][2]),"q3":text(r["messages"][4]),"gold":[text(r["messages"][i]) for i in (1,3,5)],"actual":{}}
  for arm,ee in events.items():
   e=sorted([e for e in ee if e["root"]==key and e["history"]=="ACTUAL_MODEL"],key=lambda x:x["turn"])
   if len(e)!=3: raise ValueError((arm,key,len(e)))
   case["actual"][arm]=[x["answer"] for x in e]
  item["cases"].append(case)
 out.append(item)
print(json.dumps(out,ensure_ascii=False))
